INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('3', '1', '1', 'Tujuan utama K3 di tempat kerja adalah…', 'Meningkatkan estetika ruang kerja', 'Menjamin keselamatan dan kesehatan pekerja melalui pencegahan kecelakaan/PAK', 'Menambah jam kerja efektif', 'Mengurangi kebutuhan SOP', 'b', NULL, '2026-06-01 11:20:20', '2026-06-01 11:20:20', 'multiple_choice', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('4', '1', '1', 'Yang termasuk indikator keberhasilan Week 1 adalah…', 'Mampu memperbaiki panel listrik studio', 'Mampu menjelaskan konsep K3 secara lisan/tulisan dengan benar', 'Mampu menyusun sertifikasi ISO 9001 lengkap', 'Mampu mengoperasikan kamera multi-cam', 'b', NULL, '2026-06-01 11:20:20', '2026-06-01 11:20:20', 'multiple_choice', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('5', '1', '1', '“Risk mapping” paling tepat dipahami sebagai…', 'Daftar inventaris alat studio', 'Pemetaan bahaya–risiko–kontrol awal–PIC untuk prioritas tindakan', 'Jadwal produksi mingguan', 'Data presensi kru produksi', 'b', NULL, '2026-06-01 11:20:20', '2026-06-01 11:20:20', 'multiple_choice', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('6', '1', '1', 'Dalam konteks studio TV, contoh hazard yang tepat adalah…', 'Cedera keseleo', 'Kabel power melintang jalur kru (trip hazard)', 'Biaya produksi tinggi', 'Video hasil akhir kurang menarik', 'b', NULL, '2026-06-01 11:20:20', '2026-06-01 11:20:20', 'multiple_choice', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('7', '1', '2', 'Segitiga api terdiri dari…', 'Bahan bakar – air – asap', 'Panas – bahan bakar – oksigen', 'Oksigen – listrik – air', 'Panas – udara – logam', 'b', NULL, '2026-06-01 11:20:20', '2026-06-01 11:20:20', 'multiple_choice', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('8', '1', '2', 'Kebakaran kelas A umumnya berasal dari…', 'Logam reaktif', 'Cairan mudah terbakar', 'Bahan padat non-logam (kayu/kertas/kain)', 'Minyak goreng di dapur', 'c', NULL, '2026-06-01 11:20:20', '2026-06-01 11:20:20', 'multiple_choice', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('9', '1', '2', 'Jika sumber api berasal dari peralatan listrik bertegangan, kelas kebakaran yang paling sesuai adalah…', 'A', 'B', 'C', 'K', 'c', NULL, '2026-06-01 11:20:20', '2026-06-01 11:20:20', 'multiple_choice', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('10', '1', '2', 'Tindakan awal paling prioritas saat tercium bau kabel terbakar adalah…', 'Melanjutkan produksi agar tidak terlambat', 'Stop work, amankan orang, lapor PIC, identifikasi sumber secara aman', 'Menutup semua pintu agar asap tidak keluar', 'Menyiram air ke panel listrik', 'b', NULL, '2026-06-01 11:20:20', '2026-06-01 11:20:20', 'multiple_choice', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('11', '1', '3', 'Komponen Fire Safety Management yang benar adalah…', 'Prevention–Preparedness–Response–Recovery', 'Ideate–Prototype–Test–Deploy', 'Budgeting–Marketing–Sales–Support', 'Planning–Shooting–Editing–Publishing', 'a', NULL, '2026-06-01 11:20:20', '2026-06-01 11:20:20', 'multiple_choice', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('12', '1', '3', 'Checklist pra-produksi kebakaran paling tepat berisi…', 'Daftar talent dan kostum', 'Pengecekan APAR, jalur evakuasi, beban listrik, housekeeping kabel', 'Struktur organisasi jurusan', 'Naskah acara lengkap', 'b', NULL, '2026-06-01 11:20:20', '2026-06-01 11:20:20', 'multiple_choice', NULL, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('13', '1', '3', '“Assembly point” adalah…', 'Ruang mixing audio', 'Titik kumpul evakuasi saat keadaan darurat', 'Ruang editing', 'Tempat penyimpanan kabel', 'b', NULL, '2026-06-01 11:20:20', '2026-06-01 11:20:20', 'multiple_choice', NULL, NULL, NULL, NULL);
