INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('275', '2', '15', 'Tentukan pernyataan yang benar tentang controller pada Laravel.', 'Controller dapat digunakan untuk mengelompokkan logika penanganan request.', 'Controller hanya berisi kode CSS untuk mengatur tampilan.', 'Controller wajib ditulis di dalam file database migration.', 'Controller tidak boleh dipanggil melalui route.', 'a', 'Controller membantu merapikan logika aplikasi agar tidak semua request ditangani langsung di file route.', '2026-06-02 03:49:45', '2026-06-02 03:49:45', 'true_false', '{"a":true,"b":false,"c":false,"d":false}', NULL, NULL, NULL);
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('276', '2', '15', 'Tentukan pernyataan yang benar tentang Blade.', 'Blade adalah template engine yang digunakan Laravel untuk membuat view.', 'Blade adalah database bawaan Laravel.', 'File Blade selalu berekstensi .css.', 'Blade digunakan untuk mengganti fungsi web server.', 'a', 'Blade adalah template engine untuk tampilan/view dan umumnya menggunakan file berekstensi .blade.php.', '2026-06-02 03:49:45', '2026-06-02 03:49:45', 'true_false', '{"a":true,"b":false,"c":false,"d":false}', NULL, NULL, NULL);
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('277', '2', '15', 'Tentukan pernyataan yang benar tentang Eloquent ORM.', 'Eloquent ORM memudahkan interaksi model Laravel dengan tabel database.', 'Eloquent digunakan untuk mengatur warna background halaman.', 'Eloquent hanya dapat menjalankan JavaScript di browser.', 'Eloquent tidak berhubungan dengan database sama sekali.', 'a', 'Eloquent adalah ORM Laravel yang menghubungkan model dengan operasi data seperti membaca, menambah, mengubah, dan menghapus record.', '2026-06-02 03:49:45', '2026-06-02 03:49:45', 'true_false', '{"a":true,"b":false,"c":false,"d":false}', NULL, NULL, NULL);
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('278', '2', '15', 'Tentukan pernyataan yang benar tentang migration pada Laravel.', 'Migration digunakan untuk mendefinisikan dan mengelola perubahan struktur database.', 'Migration berfungsi mengubah file gambar menjadi video.', 'Migration hanya digunakan untuk menulis style CSS.', 'Migration tidak dapat dibuat melalui perintah Artisan.', 'a', 'Migration membantu mengatur skema database secara terstruktur dan dapat dibuat menggunakan perintah Artisan.', '2026-06-02 03:49:45', '2026-06-02 03:49:45', 'true_false', '{"a":true,"b":false,"c":false,"d":false}', NULL, NULL, NULL);
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('279', '2', '15', 'Tentukan pernyataan yang benar tentang Artisan.', 'Artisan adalah command-line interface bawaan Laravel.', 'Artisan adalah aplikasi desain grafis untuk membuat logo.', 'Artisan hanya digunakan di sisi browser tanpa terminal.', 'Artisan tidak dapat digunakan untuk membuat controller atau migration.', 'a', 'Artisan menyediakan perintah terminal untuk membantu pengembangan, misalnya membuat controller, model, middleware, atau migration.', '2026-06-02 03:49:45', '2026-06-02 03:49:45', 'true_false', '{"a":true,"b":false,"c":false,"d":false}', NULL, NULL, NULL);
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('280', '2', '15', 'Tentukan pernyataan yang benar tentang middleware pada Laravel.', 'Middleware dapat digunakan untuk memeriksa atau memfilter request sebelum masuk ke aplikasi.', 'Middleware hanya berfungsi untuk memperbesar ukuran font.', 'Middleware tidak bisa dipakai untuk autentikasi.', 'Middleware wajib ditulis di file HTML.', 'a', 'Middleware berada di antara request dan aplikasi, misalnya untuk autentikasi, logging, atau proteksi request.', '2026-06-02 03:49:45', '2026-06-02 03:49:45', 'true_false', '{"a":true,"b":false,"c":false,"d":false}', NULL, NULL, NULL);
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('281', '2', '15', 'Tentukan pernyataan yang benar tentang CSRF pada Laravel.', 'CSRF protection membantu memastikan request form berasal dari sumber yang sah.', 'CSRF digunakan untuk membuat tabel HTML.', 'Token CSRF hanya diperlukan untuk mengubah warna teks.', 'Directive @csrf digunakan untuk membuat file CSS baru.', 'a', 'CSRF protection melindungi request form seperti POST, PUT, PATCH, dan DELETE dengan token validasi.', '2026-06-02 03:49:45', '2026-06-02 03:49:45', 'true_false', '{"a":true,"b":false,"c":false,"d":false}', NULL, NULL, NULL);
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('282', '2', '15', 'Tentukan pernyataan yang benar tentang file .env pada Laravel.', 'File .env digunakan untuk menyimpan konfigurasi lingkungan seperti koneksi database.', 'File .env adalah file utama untuk menulis semua tag HTML.', 'File .env selalu dikirim langsung ke browser pengguna.', 'File .env digunakan untuk mendesain layout halaman dengan CSS.', 'a', 'File .env menyimpan konfigurasi environment aplikasi, misalnya APP_NAME, APP_ENV, DB_DATABASE, DB_USERNAME, dan DB_PASSWORD.', '2026-06-02 03:49:45', '2026-06-02 03:49:45', 'true_false', '{"a":true,"b":false,"c":false,"d":false}', NULL, NULL, NULL);
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('283', '2', '15', 'Tentukan semua pernyataan yang benar tentang alur request sederhana di Laravel.', 'URL yang diakses pengguna dapat dipetakan melalui route.', 'Route dapat diarahkan ke method pada controller.', 'Controller dapat mengembalikan view kepada pengguna.', 'View bertugas langsung membuat tabel database tanpa model atau migration.', 'a', 'Alur umum Laravel dapat dimulai dari route, dilanjutkan ke controller, lalu controller mengembalikan view. Pembuatan tabel database bukan tugas utama view.', '2026-06-02 03:49:45', '2026-06-02 03:49:45', 'true_false', '{"a":true,"b":true,"c":true,"d":false}', NULL, NULL, NULL);
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('284', '2', '15', 'Tentukan semua pernyataan yang benar tentang pengelolaan database di Laravel.', 'Migration membantu mendokumentasikan perubahan struktur tabel database.', 'Eloquent model dapat mewakili tabel database tertentu.', 'Seeder dapat digunakan untuk mengisi data awal atau data contoh.', 'Relasi database hanya dapat ditulis di file CSS.', 'a', 'Migration, model Eloquent, dan seeder adalah bagian umum dalam pengelolaan database Laravel. Relasi database tidak ditulis di file CSS.', '2026-06-02 03:49:45', '2026-06-02 03:49:45', 'true_false', '{"a":true,"b":true,"c":true,"d":false}', NULL, NULL, NULL);
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('285', '2', '15', 'Tentukan semua pernyataan yang benar tentang keamanan dasar Laravel.', 'Middleware auth dapat digunakan untuk membatasi akses halaman tertentu.', 'Form POST, PUT, PATCH, dan DELETE pada route web sebaiknya menyertakan token CSRF.', 'Validation membantu memastikan input pengguna sesuai aturan yang ditentukan.', 'Password pengguna sebaiknya disimpan dalam bentuk teks biasa agar mudah dibaca admin.', 'a', 'Autentikasi, CSRF, dan validasi adalah praktik keamanan dasar. Password tidak boleh disimpan sebagai teks biasa.', '2026-06-02 03:49:45', '2026-06-02 03:49:45', 'true_false', '{"a":true,"b":true,"c":true,"d":false}', NULL, NULL, NULL);
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('286', '2', '15', 'Tentukan semua pernyataan yang benar tentang Blade dan view pada Laravel.', 'Blade dapat berisi HTML dan directive Blade.', 'File Blade umumnya disimpan di folder resources/views.', 'Blade layout dapat membantu mengurangi pengulangan struktur tampilan seperti header dan footer.', 'Blade hanya bisa digunakan untuk membuat query SQL mentah.', 'a', 'Blade digunakan untuk membuat tampilan. Layout dan directive Blade membantu menyusun UI secara lebih rapi dan reusable.', '2026-06-02 03:49:45', '2026-06-02 03:49:45', 'true_false', '{"a":true,"b":true,"c":true,"d":false}', NULL, NULL, NULL);
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('287', '2', '15', 'Tentukan semua pernyataan yang benar tentang praktik pengembangan Laravel.', 'Memisahkan route, controller, model, dan view membantu kode lebih terstruktur.', 'Perintah Artisan dapat mempercepat pembuatan file seperti controller, model, dan migration.', 'Menggunakan migration memudahkan tim menyamakan struktur database.', 'Semua logika aplikasi sebaiknya ditulis di satu file Blade agar lebih aman.', 'a', 'Pemisahan tanggung jawab membuat aplikasi lebih mudah dirawat. Menumpuk semua logika di satu file Blade justru membuat aplikasi sulit dikembangkan.', '2026-06-02 03:49:45', '2026-06-02 03:49:45', 'true_false', '{"a":true,"b":true,"c":true,"d":false}', NULL, NULL, NULL);
