INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('388', '4', '13', 'Perhatikan gambar arsitektur web server. Jelaskan alur kerja ketika browser membuka sebuah halaman web mulai dari request, pemrosesan server, akses data, sampai response diterima kembali oleh browser.', 'Uraikan komponen utama.', 'Jelaskan alur kerja.', 'Analisis keterkaitan antarbagian.', 'Berikan kesimpulan teknis.', 'a', 'Jawaban kuat menjelaskan browser/client, DNS/request HTTP, web server, aplikasi backend, database, response HTML/CSS/JS, status code, dan alasan tiap komponen saling terhubung.', '2026-06-03 12:34:02', '2026-06-03 12:34:02', 'hots', NULL, NULL, 'berat', '/hots/web-server-architecture.svg');
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('389', '4', '14', 'Perhatikan gambar cara kerja Laravel. Jelaskan bagaimana request masuk ke aplikasi Laravel, melewati routing, controller, model/database, view, lalu menjadi response.', 'Uraikan komponen utama.', 'Jelaskan alur kerja.', 'Analisis keterkaitan antarbagian.', 'Berikan kesimpulan teknis.', 'a', 'Jawaban kuat menyebut public/index.php, middleware, route, controller, model/Eloquent, database, Blade/view atau JSON response, serta peran MVC.', '2026-06-03 12:34:02', '2026-06-03 12:34:02', 'hots', NULL, NULL, 'berat', '/hots/laravel-request-lifecycle.svg');
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('390', '4', '15', 'Perhatikan gambar cara kerja template tampilan Laravel. Jelaskan bagaimana layout Blade, section/yield, component/partial, asset CSS/JS, dan data dari controller membentuk tampilan halaman.', 'Uraikan komponen utama.', 'Jelaskan alur kerja.', 'Analisis keterkaitan antarbagian.', 'Berikan kesimpulan teknis.', 'a', 'Jawaban kuat menjelaskan layout utama, @yield/@section, @include/component, variable data dari controller, asset Vite/public, dan hasil render HTML.', '2026-06-03 12:34:02', '2026-06-03 12:34:02', 'hots', NULL, NULL, 'berat', '/hots/laravel-blade-template.svg');
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('391', '4', '16', 'Perhatikan gambar alur mengganti template pada web portofolio/CV. Jelaskan langkah teknis mengganti template agar konten portofolio tetap dinamis dan tidak merusak route, asset, maupun data.', 'Uraikan komponen utama.', 'Jelaskan alur kerja.', 'Analisis keterkaitan antarbagian.', 'Berikan kesimpulan teknis.', 'a', 'Jawaban kuat memuat analisis template lama/baru, pemetaan layout, pemindahan asset, penyesuaian Blade, data dinamis profil/proyek, route/controller, pengujian responsive, dan validasi link.', '2026-06-03 12:34:02', '2026-06-03 12:34:02', 'hots', NULL, NULL, 'berat', '/hots/portfolio-template-change.svg');
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('392', '5', '13', 'Jelaskan fungsi setiap tahap pada pipeline animasi 3D, identifikasi tahapan yang paling menentukan kualitas visual akhir, dan berikan alasan Anda.', 'Uraikan komponen utama.', 'Jelaskan alur kerja.', 'Analisis keterkaitan antarbagian.', 'Berikan kesimpulan teknis.', 'a', 'Jawaban kuat menjelaskan alur dari ide cerita, script, storyboard, desain karakter/environment, modeling, texturing/shading, rigging, layout/camera, animation, lighting, rendering, compositing, editing, sampai output final. Analisis harus menyebut hubungan antar tahap dan memilih tahap paling menentukan kualitas visual dengan alasan teknis.', '2026-06-08 05:41:35', '2026-06-08 05:41:35', 'hots', NULL, NULL, 'berat', '/hots/animasi-3d/soal-hots-animasi-3d-1.png');
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('393', '5', '14', 'Analisis perbedaan pendekatan render real-time dan offline. Menurut Anda, kapan Unity lebih tepat digunakan, dan kapan offline renderer lebih unggul? Jelaskan berdasarkan kebutuhan produksi.', 'Uraikan komponen utama.', 'Jelaskan alur kerja.', 'Analisis keterkaitan antarbagian.', 'Berikan kesimpulan teknis.', 'a', 'Jawaban kuat membandingkan kecepatan, kualitas visual, interaktivitas, hardware, penggunaan utama, global illumination, refleksi/bayangan, dan workflow. Unity tepat untuk game, VR/AR, simulasi, training, dan previs cepat; offline renderer unggul untuk film, iklan, VFX, arsitektur, dan visual fotorealistis.', '2026-06-08 05:41:35', '2026-06-08 05:41:35', 'hots', NULL, NULL, 'berat', '/hots/animasi-3d/soal-hots-animasi-3d-2.png');
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('394', '5', '15', 'Jelaskan konsep bumper dan peran compositing di dalamnya. Analisis bagaimana compositing dapat meningkatkan kualitas komunikasi visual sebuah bumper.', 'Uraikan komponen utama.', 'Jelaskan alur kerja.', 'Analisis keterkaitan antarbagian.', 'Berikan kesimpulan teknis.', 'a', 'Jawaban kuat menjelaskan bumper sebagai video pendek pembuka/penutup untuk identitas visual, durasi singkat, logo, teks, musik, dan motion graphic. Compositing dibahas sebagai proses layering, color correction, VFX, dan final look yang memperkuat pesan, fokus visual, ritme, dan konsistensi brand.', '2026-06-08 05:41:35', '2026-06-08 05:41:35', 'hots', NULL, NULL, 'berat', '/hots/animasi-3d/soal-hots-animasi-3d-3.png');
INSERT INTO "questions" ("id", "exam_id", "week", "question_text", "option_a", "option_b", "option_c", "option_d", "correct_option", "explanation", "created_at", "updated_at", "question_type", "correct_options", "class_name", "level", "image_url") VALUES ('395', '5', '16', 'Berdasarkan pipeline di atas, jelaskan urutan kerja yang efektif untuk menghasilkan render atau compositing yang baik. Tahap mana yang paling berisiko menimbulkan kesalahan jika diabaikan? Berikan analisis Anda.', 'Uraikan komponen utama.', 'Jelaskan alur kerja.', 'Analisis keterkaitan antarbagian.', 'Berikan kesimpulan teknis.', 'a', 'Jawaban kuat menjelaskan urutan scene preparation, model check, material/texture check, lighting setup, camera setup, render passes, compositing, color correction, review/QC, dan final output. Analisis risiko bisa menekankan model check, material/texture, lighting, render passes, atau QC dengan alasan dampaknya pada artefak, noise, konsistensi, dan kebutuhan revisi.', '2026-06-08 05:41:35', '2026-06-08 05:41:35', 'hots', NULL, NULL, 'berat', '/hots/animasi-3d/soal-hots-animasi-3d-4.png');
