PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;

DROP TABLE IF EXISTS "attempt_answers";
CREATE TABLE "attempt_answers" ("id" integer primary key autoincrement not null, "attempt_id" integer not null, "question_id" integer not null, "selected_option" varchar, "is_correct" tinyint(1), "answered_at" datetime, "created_at" datetime, "updated_at" datetime, "display_order" integer not null default '0', "selected_options" text, "essay_answer" text, foreign key("attempt_id") references "attempts"("id") on delete cascade, foreign key("question_id") references "questions"("id") on delete cascade);

DROP TABLE IF EXISTS "attempts";
CREATE TABLE "attempts" ("id" integer primary key autoincrement not null, "exam_id" integer not null, "user_id" integer not null, "started_at" datetime not null, "ends_at" datetime not null, "submitted_at" datetime, "status" varchar not null default ('in_progress'), "score" integer not null default ('0'), "total_questions" integer not null default ('60'), "created_at" datetime, "updated_at" datetime, "percentage" numeric not null default ('0'), "letter_grade" varchar, "numeric_grade" numeric, "grade_category" varchar, "exam_package_id" integer, "shuffle_pattern" integer not null default '1', "proctor_warnings" integer not null default '0', "proctor_violation" tinyint(1) not null default '0', "proctor_events" text, foreign key("user_id") references users("id") on delete cascade on update no action, foreign key("exam_id") references exams("id") on delete cascade on update no action, foreign key("exam_package_id") references "exam_packages"("id") on delete set null);

DROP TABLE IF EXISTS "cache";
CREATE TABLE "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));

DROP TABLE IF EXISTS "cache_locks";
CREATE TABLE "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));

DROP TABLE IF EXISTS "courses";
CREATE TABLE "courses" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);

DROP TABLE IF EXISTS "exam_package_question";
CREATE TABLE "exam_package_question" ("id" integer primary key autoincrement not null, "exam_package_id" integer not null, "question_id" integer not null, "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("exam_package_id") references "exam_packages"("id") on delete cascade, foreign key("question_id") references "questions"("id") on delete cascade);

DROP TABLE IF EXISTS "exam_packages";
CREATE TABLE "exam_packages" ("id" integer primary key autoincrement not null, "exam_id" integer not null, "name" varchar not null, "code" varchar not null, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("exam_id") references "exams"("id") on delete cascade);

DROP TABLE IF EXISTS "exams";
CREATE TABLE "exams" ("id" integer primary key autoincrement not null, "title" varchar not null, "duration_minutes" integer not null default ('60'), "is_active" tinyint(1) not null default ('1'), "created_at" datetime, "updated_at" datetime, "course_id" integer, "opens_at" datetime, "closes_at" datetime, "class_name" varchar, foreign key("course_id") references "courses"("id") on delete set null);

DROP TABLE IF EXISTS "failed_jobs";
CREATE TABLE "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);

DROP TABLE IF EXISTS "grade_scales";
CREATE TABLE "grade_scales" ("id" integer primary key autoincrement not null, "course_id" integer not null, "min_score" numeric not null, "max_score" numeric not null, "include_min" tinyint(1) not null default '1', "include_max" tinyint(1) not null default '0', "letter_grade" varchar not null, "numeric_grade" numeric, "category" varchar, "description" varchar, "sort_order" integer not null default '0', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("course_id") references "courses"("id") on delete cascade);

DROP TABLE IF EXISTS "job_batches";
CREATE TABLE "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));

DROP TABLE IF EXISTS "jobs";
CREATE TABLE "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);

DROP TABLE IF EXISTS "migrations";
CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);

DROP TABLE IF EXISTS "password_reset_tokens";
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));

DROP TABLE IF EXISTS "personal_access_tokens";
CREATE TABLE "personal_access_tokens" ("id" integer primary key autoincrement not null, "tokenable_type" varchar not null, "tokenable_id" integer not null, "name" text not null, "token" varchar not null, "abilities" text, "last_used_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime);

DROP TABLE IF EXISTS "questions";
CREATE TABLE "questions" ("id" integer primary key autoincrement not null, "exam_id" integer not null, "week" integer, "question_text" text not null, "option_a" text not null, "option_b" text not null, "option_c" text not null, "option_d" text not null, "correct_option" varchar not null, "explanation" text, "created_at" datetime, "updated_at" datetime, "question_type" varchar not null default 'multiple_choice', "correct_options" text, "class_name" varchar, "level" varchar, "image_url" text, foreign key("exam_id") references "exams"("id") on delete cascade);
